    objs = {}
    for c in colors:
        pts = [(r, x) for r in range(h) for x in range(w) if grid[r][x] == c]
        objs[c] = (pts, min(r for r, x in pts), max(r for r, x in pts))
    # Color 8 is the fixed reference object in the examples; every other
    # object is translated vertically to share its top row.
    anchor = 8 if 8 in objs else max(colors, key=lambda c: objs[c][2] - objs[c][1])
    target_top = objs[anchor][1]
    out = [[0] * w for _ in range(h)]
    for c, (pts, top, bottom) in objs.items():
        dr = target_top - top
        for r, x in pts:
            rr = r + dr
            if 0 <= rr < h:
                out[rr][x] = c
    return out
