 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    pts_by_color = {c: [(r, x) for r in range(h) for x in range(w) if grid[r][x] == c] for c in colors}
    # Each colored object is an image to align into a shared horizontal band.
    # Reference band begins at the topmost colored row.
    top = min(r for pts in pts_by_color.values() for r, x in pts)
    out = [[0] * w for _ in range(h)]
    for c, pts in pts_by_color.items():
        r0 = min(r for r, x in pts)
        shift = top - r0
        for r, x in pts:
            rr = r + shift
            if 0 <= rr < h:
                out[rr][x] = c
    return out
